# Calculate the inner measure by finding the values in y1 that correspond to the target times t0
# This is done by finding the indices of the source times t1 that are less than or equal to the target times t0
inner_measure = torch.zeros_like(t0)
for i in range(len(t0)):
    idx = torch.searchsorted(t1, t0[i])
    if idx == len(t1):
        inner_measure[i] = cum_sum_y1[-1]
    elif idx == 0:
        inner_measure[i] = 0
    else:
        inner_measure[i] = cum_sum_y1[idx-1]

# Calculate the outer measure by finding the values in y1 that correspond to the target times t0
# This is done by finding the indices of the source times t1 that are greater than the target times t0
outer_measure = torch.zeros_like(t0)
for i in range(len(t0)):
    idx = torch.searchsorted(t1, t0[i]) - 1
    if idx < 0:
        outer_measure[i] = 0
    elif idx == len(t1) - 1:
        outer_measure[i] = cum_sum_y1[-1]
    else:
        outer_measure[i] = cum_sum_y1[idx+1] - cum_sum_y1[idx]

return inner_measure

